 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Detect solid rectangular outlines by color.
    frames = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                     if r in (r0, r1) or c in (c0, c1)}
        if all(grid[r][c] == color for r, c in perimeter) and len(cells) == len(perimeter):
            frames.append((r0, r1, c0, c1, color))

    frame_cells = set()
    for r0, r1, c0, c1, color in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    frame_cells.add((r, c))

    # The scattered pixels encode the fill color: each color's count equals
    # the number of even-parity cells in its corresponding frame interior.
    counts = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r, c) not in frame_cells:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1

    out = [[0] * w for _ in range(h)]
    for r0, r1, c0, c1, border in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = border
        target = sum(1 for r in range(r0 + 1, r1) for c in range(c0 + 1, c1) if (r + c) % 2 == 0)
        fill = next((col for col, n in counts.items() if n == target), None)
        if fill is not None:
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if (r + c) % 2 == 0:
                        out[r][c] = fill
    return out
